type Tab = 'analytics' | 'blog' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages' | 'security';

const Dashboard: React.FC = () => {
  const { 
    posts, podcasts, books, merch, comments, pages, adminConfig,
    addPost, updatePost, addPodcast, addBook, addMerch, addPage, updatePage, updateCommentStatus, deleteItem, updateAdmin
  } = useData();
  const { showToast } = useToast();

  const [activeTab, setActiveTab] = useState<Tab>('analytics');
  const bookFileRef = useRef<HTMLInputElement>(null);
  const merchFileRef = useRef<HTMLInputElement>(null);
  const pageFileRef = useRef<HTMLInputElement>(null);
  const blogFileRef = useRef<HTMLInputElement>(null);

  const blogEditorRef = useRef<HTMLDivElement>(null);
  const pageEditorRef = useRef<HTMLDivElement>(null);

  // Form States
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'Truth' as BlogCategory, image: '' });
  const [editingPostId, setEditingPostId] = useState<string | null>(null);

  const [podcastForm, setPodcastForm] = useState({ title: '', embedUrl: '', platform: 'YouTube' as any });
  const [bookForm, setBookForm] = useState({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' as any });
  const [merchForm, setMerchForm] = useState({ title: '', description: '', image: '', link: '', platform: 'TeePublic' as any });
  const [pageForm, setPageForm] = useState({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
  const [editingPageId, setEditingPageId] = useState<string | null>(null);

  // Security State
  const [securityForm, setSecurityForm] = useState({ currentPassword: '', newEmail: adminConfig.email, newPassword: '', confirmPassword: '' });

  // Sync security form with adminConfig if config updates
  useEffect(() => {
    setSecurityForm(prev => ({ ...prev, newEmail: adminConfig.email }));
  }, [adminConfig.email]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'book' | 'merch' | 'page' | 'post') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'book') setBookForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'merch') setMerchForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'page') setPageForm(prev => ({ ...prev, featuredImage: base64String }));
        else if (type === 'post') setPostForm(prev => ({ ...prev, image: base64String }));
        showToast("Visual asset buffered for deployment.", "info");
      };
      reader.readAsDataURL(file);
    }
  };

  const execCmd = (command: string, value: string = '', editor: 'blog' | 'page') => {
    document.execCommand(command, false, value);
    const targetRef = editor === 'blog' ? blogEditorRef : pageEditorRef;
    if (targetRef.current) {
      if (editor === 'blog') setPostForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
      else setPageForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
    }
  };

  const handleSavePost = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = blogEditorRef.current?.innerHTML || '';
    const payload = { ...postForm, content: finalContent };

    if (editingPostId) {
      updatePost(editingPostId, payload);
      showToast("Intel Node updated successfully.", "success");
    } else {
      addPost(payload);
      showToast("New Intel unsealed and broadcasted.", "success");
