      title: post.title,
      excerpt: post.excerpt,
      content: post.content,
      category: post.category,
      image: post.image
    });
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = post.content;
    setActiveTab('blog');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

