    resetPostForm();
  };

  const resetPostForm = () => {
    setPostForm({ title: '', excerpt: '', content: '', category: 'Truth', image: '' });
    setEditingPostId(null);
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = '';
