    e.preventDefault();
    addPodcast(podcastForm);
    setPodcastForm({ 
      title: '', 
      description: '', 
      thumbnail: '', 
      episodeNumber: podcasts.length + 2, 
      embedUrl: '', 
      platform: 'YouTube' 
