    e.preventDefault();
    const cleanCurrent = securityForm.currentPassword.trim();
    if (cleanCurrent !== adminConfig.passwordHash) {
      showToast("Current Access Cipher invalid. Authorization failed.", "error");
      return;
    }
    if (securityForm.newPassword !== securityForm.confirmPassword) {
      showToast("New Ciphers do not match.", "error");
      return;
    }
    if (!securityForm.newEmail.trim().endsWith('@gmail.com')) {
      showToast("Identity must be a verified Gmail node.", "error");
      return;
    }
    updateAdmin({
      email: securityForm.newEmail.trim(),
      passwordHash: securityForm.newPassword.trim() || adminConfig.passwordHash
    });
    showToast("Veil Protocols Updated. Credentials Secured.", "success");
    setSecurityForm({ ...securityForm, currentPassword: '', newPassword: '', confirmPassword: '' });
  };

  const handleDelete = (type: any, id: string) => {
    deleteItem(type, id);
    showToast(`${type.charAt(0).toUpperCase() + type.slice(1)} node de-initialized.`, "info");
  };

  const insertImage = (editor: 'blog' | 'page') => {
    const url = prompt("Enter Visual Data URL:");
    if (url) execCmd('insertImage', url, editor);
  };

  const systemPages = pages.filter(p => p.slug === 'privacy-policy' || p.slug === 'terms-of-service');
  const customPages = pages.filter(p => p.slug !== 'privacy-policy' && p.slug !== 'terms-of-service');

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 md:p-10 font-exo">
