        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div>
            <h1 className="font-orbitron font-black text-4xl mb-2 tracking-tight text-white uppercase">Command Center</h1>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Protocol: <span className="text-slate-300">VEIL_ACTIVE</span></p>
            </div>
          </div>
          <div className="flex bg-slate-900/50 p-1.5 rounded-2xl overflow-x-auto border border-slate-800 backdrop-blur-xl">
            {(['analytics', 'blog', 'podcasts', 'books', 'merch', 'pages', 'comments', 'security'] as Tab[]).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-orbitron font-bold uppercase tracking-widest transition-all whitespace-nowrap ${
                  activeTab === tab ? 'gradient-bg text-white shadow-lg shadow-brand-start/20' : 'text-slate-500 hover:text-white'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </header>

        {activeTab === 'analytics' && (
          <div className="animate-wipe-in">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
              {[
                { label: 'VISITOR COUNT', value: '124,502', trend: '+12%', color: 'text-brand-start' },
                { label: 'STREAM LISTENERS', value: '45,201', trend: '+18%', color: 'text-brand-start' },
                { label: 'BLOG POSTS', value: posts.length, trend: `+${posts.length}`, color: 'text-blue-400' },
                { label: 'BOOKS ISSUED', value: books.length, trend: `+${books.length}`, color: 'text-orange-400' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900/50 border border-slate-800 p-6 rounded-3xl relative overflow-hidden group">
                  <p className="text-slate-500 font-orbitron font-bold text-[10px] tracking-widest mb-2 uppercase">{stat.label}</p>
                  <div className="flex items-end justify-between">
                    <span className={`text-3xl font-orbitron font-black ${stat.color}`}>{stat.value}</span>
                    <span className="text-green-500 text-xs font-bold">{stat.trend}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-slate-900/50 border border-slate-800 p-8 rounded-[40px] backdrop-blur-md h-[400px]">
                 <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-slate-500 mb-8">Neural Stream Engagement</h3>
                 <ResponsiveContainer width="100%" height="100%">
