import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { BRAND_LOGO_URL } from '../constants';
import { useData } from '../context/DataContext';
import { BlogPost, PodcastEpisode, Book } from '../types';

interface NavbarProps {
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ isDarkMode, toggleTheme }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [results, setResults] = useState<{
    posts: BlogPost[];
    podcasts: PodcastEpisode[];
    books: Book[];
  }>({ posts: [], podcasts: [], books: [] });

  const { posts, podcasts, books } = useData();
  const location = useLocation();
  const navigate = useNavigate();
  const searchRef = useRef<HTMLDivElement>(null);

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Blog', path: '/blog' },
    { name: 'Podcast', path: '/podcast' },
    { name: 'Books', path: '/books' },
    { name: 'Merch', path: '/merch' },
    { name: 'About', path: '/about' },
    { name: 'Connect', path: '/connect' },
  ];

  const isActive = (path: string) => location.pathname === path;

  // Search Logic
  useEffect(() => {
    if (searchQuery.length < 2) {
      setResults({ posts: [], podcasts: [], books: [] });
      return;
    }

    const q = searchQuery.toLowerCase();

    const filteredPosts = posts.filter(p => 
      p.title.toLowerCase().includes(q) || p.excerpt.toLowerCase().includes(q)
    ).slice(0, 3);

    const filteredPodcasts = podcasts.filter(p => 
      p.title.toLowerCase().includes(q) || p.description.toLowerCase().includes(q)
    ).slice(0, 3);

    const filteredBooks = books.filter(b => 
      b.title.toLowerCase().includes(q) || b.subtitle.toLowerCase().includes(q) || b.description.toLowerCase().includes(q)
    ).slice(0, 3);

    setResults({ posts: filteredPosts, podcasts: filteredPodcasts, books: filteredBooks });
  }, [searchQuery, posts, podcasts, books]);

  // Handle outside click to close search
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setIsSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const closeSearch = () => {
    setIsSearchOpen(false);
    setSearchQuery('');
  };

  const navigateTo = (path: string) => {
    navigate(path);
    closeSearch();
  };

  return (
    <nav className="fixed top-0 w-full z-50 backdrop-blur-lg bg-white/80 dark:bg-slate-950/80 border-b border-slate-200 dark:border-slate-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-3">
              <div className="w-10 h-10 overflow-hidden rounded-full flex items-center justify-center border border-slate-200 dark:border-slate-800 shadow-sm bg-slate-100 dark:bg-slate-900">
                <img 
                  src={BRAND_LOGO_URL} 
                  alt="Trick Theology Logo" 
                  className="w-full h-full object-cover scale-110"
                  onError={(e) => {
                    e.currentTarget.style.display = 'none';
                    e.currentTarget.parentElement!.innerHTML = '<div class="w-full h-full gradient-bg flex items-center justify-center font-orbitron font-bold text-white text-[10px]">TT</div>';
                  }}
                />
              </div>
              <span className="font-orbitron font-bold text-lg hidden lg:block tracking-tighter uppercase">
                <span className="text-brand-start">TRICK</span> THEOLOGY
              </span>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-6">
            <div className="relative" ref={searchRef}>
              <div className={`flex items-center bg-slate-100 dark:bg-slate-900 rounded-full border transition-all duration-300 ${isSearchOpen ? 'w-64 border-brand-start/50' : 'w-10 border-transparent'}`}>
                <button 
                  onClick={() => setIsSearchOpen(!isSearchOpen)}
                  className="p-2 text-slate-500 hover:text-brand-start transition-colors"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </button>
                {isSearchOpen && (
                  <input
                    autoFocus
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search the Veil..."
                    className="bg-transparent border-none outline-none text-xs font-orbitron font-bold text-slate-800 dark:text-white w-full pr-4 placeholder:text-slate-500"
                  />
                )}
              </div>

              {/* Search Results Dropdown */}
              {isSearchOpen && searchQuery.length >= 2 && (
                <div className="absolute top-12 right-0 w-[400px] bg-white dark:bg-slate-900/95 backdrop-blur-2xl border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl p-6 animate-wipe-in max-h-[80vh] overflow-y-auto custom-scrollbar">
                  <div className="space-y-8">
                    {/* Blog Results */}
                    {results.posts.length > 0 && (
                      <div>
                        <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-4 tracking-[0.3em] uppercase opacity-50">Blog Nodes</h4>
                        <div className="space-y-3">
                          {results.posts.map(post => (
                            <button key={post.id} onClick={() => navigateTo('/blog')} className="w-full text-left group">
                              <p className="text-sm font-bold text-slate-800 dark:text-white group-hover:text-brand-start transition-colors uppercase truncate">{post.title}</p>
                              <p className="text-[10px] text-slate-500 truncate">{post.excerpt}</p>
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Podcast Results */}
                    {results.podcasts.length > 0 && (
