                          {results.podcasts.map(ep => (
                            <button key={ep.id} onClick={() => navigateTo('/podcast')} className="w-full text-left group">
                              <p className="text-sm font-bold text-slate-800 dark:text-white group-hover:text-brand-start transition-colors uppercase truncate">EP {ep.episodeNumber}: {ep.title}</p>
                              <p className="text-[10px] text-slate-500 truncate">{ep.description}</p>
                            </button>
                          ))}
                        </div>
                      </div>
