                    <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-6 tracking-[0.4em] uppercase">Audio Streams</h4>
                    <div className="space-y-6">
                      {results.podcasts.map(ep => (
                        <button key={ep.id} onClick={() => navigateTo('/podcast')} className="w-full text-left">
                           <p className="font-bold uppercase text-brand-start text-xs mb-1">Episode {ep.episodeNumber}</p>
                          <p className="text-sm font-bold text-slate-800 dark:text-white uppercase leading-tight">{ep.title}</p>
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {results.books.length > 0 && (
                  <div>
                    <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-6 tracking-[0.4em] uppercase">Manuscripts</h4>
                    <div className="space-y-6">
                      {results.books.map(book => (
                        <button key={book.id} onClick={() => navigateTo('/books')} className="w-full text-left">
                          <p className="font-bold uppercase text-brand-start text-xs mb-1">{book.platform}</p>
                          <p className="text-sm font-bold text-slate-800 dark:text-white uppercase leading-tight">{book.title}</p>
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {results.posts.length === 0 && results.podcasts.length === 0 && results.books.length === 0 && (
                  <p className="text-center text-slate-500 font-orbitron font-bold text-[10px] uppercase tracking-widest pt-10">No matches in the neural archive.</p>
                )}
              </>
            ) : (
              <p className="text-center text-slate-500 font-orbitron font-bold text-[10px] uppercase tracking-widest pt-10">Enter 2+ characters to scan nodes...</p>
            )}
          </div>
        </div>
      )}

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white dark:bg-slate-950 border-b border-slate-200 dark:border-slate-800 animate-wipe-in">
          <div className="px-4 pt-4 pb-8 space-y-2">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-4 py-3 rounded-2xl text-xs font-orbitron font-bold uppercase tracking-[0.2em] transition-all ${
                  isActive(link.path)
                    ? 'bg-brand-start/10 text-brand-start'
                    : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-900'
                }`}
              >
                {link.name}
              </Link>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
